<?php

declare(strict_types=1);

namespace ParticleAcademy\GmailInbox\Laravel\Http;

use ParticleAcademy\GmailInbox\Laravel\Events\MessageReceivedReceived;
use ParticleAcademy\GmailInbox\Triggers\MessageReceived;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Http\Response;

/*
 * GENERATED by weaver from provider/ and its Laravel emitter (src/Laravel/Http/MessageReceivedWebhook.php). Do not edit;
 * a hand-edit is destroyed by the next protocol sync. Fix weaver and regenerate.
 */

/**
 * Gmail Inbox's message_received delivery, VERIFIED before the app sees it: the raw body
 * exactly as received, the headers, checked by the trigger's own
 * scheme (oidc-jwt). A delivery that does not verify answers 401 with the
 * reason and dispatches nothing; one that does dispatches MessageReceivedReceived.
 */
final class MessageReceivedWebhook
{
    public function __invoke(Request $request): JsonResponse|Response
    {
        $raw = (string) $request->getContent();
        $headers = $request->headers->all();
        $result = MessageReceived::verifyDelivery(
            $raw,
            $headers,
            (array) config('connectors.gmail-inbox.webhook_keys', []),
            config('connectors.gmail-inbox.credentials.pushAudience'),
            config('connectors.gmail-inbox.credentials.pushServiceAccount'),
        );
        if (! $result['ok']) {
            return new JsonResponse(['ok' => false, 'reason' => $result['reason']], 401);
        }

        $payload = MessageReceived::decodeDelivery($raw);
        event(new MessageReceivedReceived($payload, $headers));

        return new JsonResponse(['ok' => true]);
    }
}
